-- +goose Up
--
-- Dual-key convention (API layer):
--   * Internal PK `id` is BIGINT GENERATED BY DEFAULT AS IDENTITY — used for all FKs,
--     joins, and indexes. Never expose in URLs or external API payloads.
--   * Public `public_id` is UUID NOT NULL UNIQUE DEFAULT gen_random_uuid() — the only
--     identifier the API/URL layer may accept or emit for addressable entities.
--   * FKs always reference the bigint `id` (never `public_id`).
--   * Junction / ownership child tables use bigint FKs only; they get `id` /
--     `public_id` only when independently addressable from the API. Pure and
--     enriched nested joins use a composite PK only (no surrogate / public_id).
--
-- Table naming:
--   * Roots: plural domain noun (members, quests, hexes, …).
--   * Pure M:N: `{left}_{right}` (member_follows, member_unlocks, quest_regions).
--   * Role/duty M:N: `*_assignments` (lieutenant_assignments, archon_assignments).
--   * 1:1 extension: `{root}_{facet}`, PK = parent FK, no public_id
--     (member_settings, dm_profiles, character_ddb_mirrors).
--   * Ledgers: `*_ledger`; domain events: `*_events`; content snapshots: `*_revisions`.
--   * Prefer `*_events` over `*_changes` for NEW history tables.
--     Legacy suffix note: role_changes / hex_changes keep `*_changes` (pre-convention).
--   * Catalogs / code tables: `*_catalog` (creation_catalog); not aggregate roots.
--
-- Rename history (vs prior draft / schema-v2):
--   * requests → dm_requests
--   * follows → member_follows
--   * maps.family → map_kind
--   * verifications.decision → verdict
--   * characters.pcxp → player_xp (cache; truth = character_progression_ledger)
--   * quests.apl → avg_party_level
--
-- Closed vocabularies use TEXT + CHECK (not Postgres ENUM) so labels can evolve
-- without ALTER TYPE. Vocab values track apps/api/docs/schema-v2.md taxonomy.

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ---------------------------------------------------------------------------
-- members / actor
-- ---------------------------------------------------------------------------
CREATE TABLE members (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    discord_id TEXT NOT NULL UNIQUE,
    handle TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    avatar_url TEXT,
    roles TEXT[] NOT NULL DEFAULT '{player}',
    status TEXT NOT NULL DEFAULT 'active',
    joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT members_roles_nonempty CHECK (cardinality(roles) >= 1),
    CONSTRAINT members_roles_vocab CHECK (
        roles <@ ARRAY['player', 'dm', 'archon', 'lieutenant', 'verifier', 'admin']::text[]
    ),
    CONSTRAINT members_status_check CHECK (status IN ('active', 'inactive', 'banned'))
);

CREATE TABLE role_changes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    member_id BIGINT NOT NULL REFERENCES members (id),
    old_roles TEXT[] NOT NULL,
    new_roles TEXT[] NOT NULL,
    changed_by BIGINT NOT NULL REFERENCES members (id),
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    note TEXT
);

CREATE INDEX role_changes_member_occurred_idx
    ON role_changes (member_id, occurred_at DESC);

CREATE TABLE member_settings (
    member_id BIGINT PRIMARY KEY REFERENCES members (id) ON DELETE CASCADE,
    theme_mode TEXT,
    timezone TEXT,
    payload JSONB NOT NULL DEFAULT '{}',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE member_availability (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    weekday SMALLINT NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    start_minute SMALLINT NOT NULL CHECK (start_minute BETWEEN 0 AND 1440),
    end_minute SMALLINT NOT NULL CHECK (end_minute BETWEEN 0 AND 1440),
    CONSTRAINT member_availability_window_check CHECK (start_minute < end_minute)
);

CREATE TABLE dm_profiles (
    member_id BIGINT PRIMARY KEY REFERENCES members (id) ON DELETE CASCADE,
    tagline TEXT,
    philosophy TEXT,
    house_rules TEXT,
    table_info JSONB,
    accepting_players BOOLEAN NOT NULL DEFAULT false,
    status TEXT NOT NULL DEFAULT 'draft',
    review_revision INT NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT dm_profiles_status_check CHECK (
        status IN ('draft', 'pending', 'approved', 'rejected')
    )
);

-- Pure M:N (member → member). Composite PK only; not independently addressable.
CREATE TABLE member_follows (
    follower_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    followed_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (follower_id, followed_id),
    CONSTRAINT member_follows_no_self CHECK (follower_id <> followed_id)
);

CREATE INDEX member_follows_followed_id_idx ON member_follows (followed_id);

-- Workflow entity (not a junction): request lifecycle with status / resolution.
CREATE TABLE dm_requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    requester_id BIGINT NOT NULL REFERENCES members (id),
    target_dm_id BIGINT NOT NULL REFERENCES dm_profiles (member_id),
    kind TEXT NOT NULL,
    note TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    resolved_by BIGINT REFERENCES members (id),
    resolved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT dm_requests_kind_check CHECK (kind IN ('quest', 'seat')),
    CONSTRAINT dm_requests_status_check CHECK (
        status IN ('pending', 'approved', 'declined', 'withdrawn')
    ),
    CONSTRAINT dm_requests_no_self CHECK (requester_id <> target_dm_id),
    CONSTRAINT dm_requests_note_len CHECK (note IS NULL OR char_length(note) <= 2000),
    CONSTRAINT dm_requests_resolved_pair CHECK (
        (status = 'pending' AND resolved_by IS NULL AND resolved_at IS NULL)
        OR (status <> 'pending' AND resolved_at IS NOT NULL)
    )
);

CREATE UNIQUE INDEX dm_requests_pending_ux
    ON dm_requests (requester_id, target_dm_id, kind)
    WHERE status = 'pending';

CREATE INDEX dm_requests_target_dm_status_idx
    ON dm_requests (target_dm_id, status);

CREATE INDEX dm_requests_requester_target_idx
    ON dm_requests (requester_id, target_dm_id);

CREATE TABLE unlockables (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    code TEXT NOT NULL UNIQUE,
    cosmetic_type TEXT NOT NULL,
    active BOOLEAN NOT NULL DEFAULT true,
    payload JSONB NOT NULL DEFAULT '{}',
    CONSTRAINT unlockables_cosmetic_type_check CHECK (
        cosmetic_type IN (
            'theme', 'palette', 'font', 'flair',
            'title', 'badge', 'frame', 'nameplate', 'token'
        )
    )
);

CREATE TABLE member_unlocks (
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    unlockable_id BIGINT NOT NULL REFERENCES unlockables (id),
    source TEXT NOT NULL,
    granted_by BIGINT REFERENCES members (id),
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (member_id, unlockable_id),
    CONSTRAINT member_unlocks_source_check CHECK (
        source IN ('milestone', 'event', 'cohort', 'grant', 'purchase')
    )
);

CREATE TABLE notifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    subject_type TEXT,
    subject_id BIGINT,
    body TEXT NOT NULL DEFAULT '',
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX notifications_member_created_idx
    ON notifications (member_id, created_at DESC);

CREATE INDEX notifications_unread_idx
    ON notifications (member_id, created_at DESC)
    WHERE read_at IS NULL;

-- ---------------------------------------------------------------------------
-- documents
-- ---------------------------------------------------------------------------
CREATE TABLE documents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    kind TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    category TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    visibility TEXT NOT NULL DEFAULT 'public',
    policy JSONB,
    body TEXT NOT NULL DEFAULT '',
    frontmatter_yaml TEXT,
    author_id BIGINT REFERENCES members (id),
    published_at TIMESTAMPTZ,
    deleted_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT documents_kind_check CHECK (
        kind IN ('codex_entry', 'rule', 'summary', 'quest_brief', 'community')
    ),
    CONSTRAINT documents_status_check CHECK (status IN ('draft', 'published')),
    CONSTRAINT documents_visibility_check CHECK (
        visibility IN ('public', 'dm_only', 'restricted')
    )
);

CREATE TABLE document_revisions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    document_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    reason TEXT NOT NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    frontmatter_yaml TEXT,
    created_by BIGINT REFERENCES members (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX document_revisions_document_created_idx
    ON document_revisions (document_id, created_at DESC);

CREATE TABLE document_links (
    source_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    target_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    relation TEXT NOT NULL DEFAULT 'link',
    PRIMARY KEY (source_id, target_id, relation)
);

CREATE INDEX document_links_target_id_idx ON document_links (target_id);

CREATE TABLE document_readers (
    document_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    PRIMARY KEY (document_id, member_id)
);

CREATE INDEX document_readers_member_id_idx ON document_readers (member_id);

CREATE TABLE lieutenant_assignments (
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    npc_document_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (member_id, npc_document_id)
);

CREATE INDEX documents_kind_status_idx
    ON documents (kind, status)
    WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------------
-- spatial (axial integers; no PostGIS in product model)
-- ---------------------------------------------------------------------------
CREATE TABLE regions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    kind TEXT NOT NULL,
    charter_deadline TIMESTAMPTZ,
    document_id BIGINT REFERENCES documents (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT regions_kind_check CHECK (kind IN ('server', 'archon', 'uncharted'))
);

CREATE TABLE maps (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    atlas_code TEXT NOT NULL UNIQUE,
    map_kind TEXT NOT NULL,
    region_id BIGINT REFERENCES regions (id),
    cols INT,
    rows INT,
    asset_path TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT maps_map_kind_check CHECK (map_kind IN ('hexgrid', 'pointcrawl')),
    CONSTRAINT maps_hexgrid_shape_check CHECK (
        map_kind <> 'hexgrid'
        OR (region_id IS NOT NULL AND cols IS NOT NULL AND rows IS NOT NULL)
    )
);

CREATE INDEX maps_region_id_idx ON maps (region_id);

CREATE TABLE hexes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    map_id BIGINT NOT NULL REFERENCES maps (id) ON DELETE CASCADE,
    col INT NOT NULL,
    row INT NOT NULL,
    terrain TEXT,
    elevation TEXT,
    climate TEXT,
    UNIQUE (map_id, col, row),
    UNIQUE (map_id, id)
);

CREATE TABLE pois (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    hex_id BIGINT NOT NULL REFERENCES hexes (id) ON DELETE CASCADE,
    poi_type TEXT NOT NULL,
    discovery_tier TEXT NOT NULL,
    is_charter_objective BOOLEAN NOT NULL DEFAULT false,
    document_id BIGINT REFERENCES documents (id),
    CONSTRAINT pois_poi_type_check CHECK (
        poi_type IN (
            'landmark', 'settlement', 'lair', 'dungeon_site', 'regional_feature'
        )
    ),
    CONSTRAINT pois_discovery_tier_check CHECK (
        discovery_tier IN ('landmark', 'hidden', 'secret')
    )
);

CREATE INDEX pois_hex_id_idx ON pois (hex_id);

-- Edge graph rows. Keep public_id while edges remain (or may become) API-addressable;
-- do not drop without a product decision that edges are never fetched by UUID.
CREATE TABLE hex_edges (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    map_id BIGINT NOT NULL REFERENCES maps (id) ON DELETE CASCADE,
    hex_a BIGINT NOT NULL,
    hex_b BIGINT NOT NULL,
    edge_type TEXT NOT NULL,
    a_side TEXT,
    document_id BIGINT REFERENCES documents (id),
    CONSTRAINT hex_edges_type_check CHECK (
        edge_type IN ('road', 'trail', 'river', 'pass', 'wall', 'ford')
    ),
    CONSTRAINT hex_edges_canonical_order CHECK (hex_a < hex_b),
    CONSTRAINT hex_edges_hex_a_same_map_fkey
        FOREIGN KEY (map_id, hex_a) REFERENCES hexes (map_id, id) ON DELETE CASCADE,
    CONSTRAINT hex_edges_hex_b_same_map_fkey
        FOREIGN KEY (map_id, hex_b) REFERENCES hexes (map_id, id) ON DELETE CASCADE
);

CREATE TABLE hex_entry_links (
    hex_id BIGINT NOT NULL REFERENCES hexes (id) ON DELETE CASCADE,
    document_id BIGINT NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    relation TEXT NOT NULL,
    PRIMARY KEY (hex_id, document_id, relation)
);

CREATE TABLE hex_changes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    hex_id BIGINT NOT NULL REFERENCES hexes (id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT hex_changes_kind_check CHECK (
        kind IN (
            'terrain_change', 'image_change', 'document_repoint', 'submap_change',
            'entry_linked', 'entry_unlinked', 'feature_added', 'razed', 'renamed'
        )
    )
);

CREATE INDEX hex_changes_hex_created_idx
    ON hex_changes (hex_id, created_at DESC);

CREATE TABLE archon_assignments (
    member_id BIGINT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
    region_id BIGINT NOT NULL REFERENCES regions (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (member_id, region_id)
);

CREATE TABLE time_anchors (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    real_utc TIMESTAMPTZ NOT NULL,
    epoch_day INT NOT NULL,
    rate DOUBLE PRECISION NOT NULL DEFAULT 1,
    note TEXT
);

CREATE TABLE game_calendar (
    id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    definition JSONB NOT NULL DEFAULT '{}'
);

CREATE TABLE game_time_map (
    real_date DATE PRIMARY KEY,
    game_day INT NOT NULL
);

-- ---------------------------------------------------------------------------
-- characters
-- ---------------------------------------------------------------------------
CREATE TABLE backstories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    lore TEXT NOT NULL DEFAULT '',
    cohort TEXT NOT NULL DEFAULT '',
    source_region_id BIGINT REFERENCES regions (id),
    retired BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE creation_catalog (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    kind TEXT NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    available BOOLEAN NOT NULL DEFAULT true,
    payload JSONB NOT NULL DEFAULT '{}',
    UNIQUE (kind, code),
    CONSTRAINT creation_catalog_kind_check CHECK (
        kind IN ('species', 'class', 'background')
    )
);

CREATE TABLE characters (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    short_code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    owner_id BIGINT NOT NULL REFERENCES members (id),
    status TEXT NOT NULL DEFAULT 'pending_approval',
    backstory_id BIGINT REFERENCES backstories (id),
    guild_document_id BIGINT REFERENCES documents (id),
    region_id BIGINT REFERENCES regions (id),
    verification_submitted_at TIMESTAMPTZ,
    -- player_xp is a cache; truth = SUM(character_progression_ledger.delta)
    player_xp INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT characters_status_check CHECK (
        status IN ('active', 'retired', 'dead', 'pending_approval')
    ),
    CONSTRAINT characters_player_xp_nonneg CHECK (player_xp >= 0)
);

CREATE TABLE character_ddb_mirrors (
    character_id BIGINT PRIMARY KEY REFERENCES characters (id) ON DELETE CASCADE,
    payload JSONB NOT NULL DEFAULT '{}',
    synced_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE character_progression_ledger (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    character_id BIGINT NOT NULL REFERENCES characters (id) ON DELETE CASCADE,
    delta INT NOT NULL,
    reason TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX character_progression_ledger_character_created_idx
    ON character_progression_ledger (character_id, created_at DESC);

CREATE TABLE downtime_projects (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    character_id BIGINT NOT NULL REFERENCES characters (id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    target INT,
    goal TEXT,
    notes TEXT,
    progress INT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'active',
    CONSTRAINT downtime_projects_status_check CHECK (
        status IN ('active', 'completed', 'abandoned')
    )
);

-- Polymorphic verification record (subject_type + subject_id). Member-owned
-- placement: decided_by → members; not a child of any single subject root.
CREATE TABLE verifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    subject_type TEXT NOT NULL,
    subject_id BIGINT NOT NULL,
    verdict TEXT NOT NULL,
    decided_by BIGINT NOT NULL REFERENCES members (id),
    note TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT verifications_verdict_check CHECK (verdict IN ('approved', 'rejected'))
);

CREATE INDEX characters_owner_idx ON characters (owner_id);
CREATE INDEX verifications_subject_idx
    ON verifications (subject_type, subject_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- quests
-- ---------------------------------------------------------------------------
CREATE TABLE quest_arcs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    created_by BIGINT NOT NULL REFERENCES members (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE quests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    short_code TEXT NOT NULL UNIQUE,
    kinds TEXT[] NOT NULL,
    status TEXT NOT NULL DEFAULT 'open',
    dm_id BIGINT NOT NULL REFERENCES members (id),
    arc_id BIGINT REFERENCES quest_arcs (id),
    scheduled_at TIMESTAMPTZ NOT NULL,
    duration_hours DOUBLE PRECISION NOT NULL DEFAULT 4,
    slots_max INT NOT NULL DEFAULT 5,
    filled_count INT NOT NULL DEFAULT 0,
    document_id BIGINT NOT NULL REFERENCES documents (id),
    tags TEXT[] NOT NULL DEFAULT '{}',
    genres TEXT[] NOT NULL DEFAULT '{}',
    -- avg_party_level is advisory metadata for the board, not a computed cache
    avg_party_level INT,
    signup_type TEXT,
    discord_desired_revision INT NOT NULL DEFAULT 0,
    discord_applied_revision INT NOT NULL DEFAULT 0,
    discord_message_id TEXT,
    discord_event_id TEXT,
    event_url TEXT,
    created_by BIGINT NOT NULL REFERENCES members (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT quests_kinds_nonempty CHECK (cardinality(kinds) >= 1),
    CONSTRAINT quests_kinds_vocab CHECK (
        kinds <@ ARRAY[
            'standard', 'event', 'lieutenant', 'hexcrawl', 'one_shot', 'mini_campaign'
        ]::text[]
    ),
    CONSTRAINT quests_status_check CHECK (
        status IN ('open', 'full', 'played', 'closed', 'cancelled')
    ),
    CONSTRAINT quests_signup_type_check CHECK (
        signup_type IS NULL
        OR signup_type IN ('open', 'application', 'invite')
    ),
    CONSTRAINT quests_duration_hours_check CHECK (duration_hours > 0),
    CONSTRAINT quests_slots_max_check CHECK (slots_max > 0 AND slots_max <= 100),
    CONSTRAINT quests_filled_count_check CHECK (
        filled_count >= 0 AND filled_count <= slots_max
    )
);

-- Enriched M:N (lifecycle status). Nested under quest; composite PK, no public_id.
CREATE TABLE quest_participants (
    quest_id BIGINT NOT NULL REFERENCES quests (id) ON DELETE CASCADE,
    member_id BIGINT NOT NULL REFERENCES members (id),
    character_id BIGINT NOT NULL REFERENCES characters (id),
    status TEXT NOT NULL DEFAULT 'signed_up',
    manual BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (quest_id, character_id),
    CONSTRAINT quest_participants_status_check CHECK (
        status IN ('signed_up', 'waitlisted', 'withdrawn', 'played', 'no_show')
    )
);

CREATE INDEX quest_participants_member_status_idx
    ON quest_participants (member_id, status);

CREATE TABLE quest_hexes (
    quest_id BIGINT NOT NULL REFERENCES quests (id) ON DELETE CASCADE,
    hex_id BIGINT NOT NULL REFERENCES hexes (id),
    role TEXT NOT NULL,
    PRIMARY KEY (quest_id, hex_id, role),
    CONSTRAINT quest_hexes_role_check CHECK (role IN ('expected', 'visited'))
);

CREATE TABLE quest_regions (
    quest_id BIGINT NOT NULL REFERENCES quests (id) ON DELETE CASCADE,
    region_id BIGINT NOT NULL REFERENCES regions (id),
    PRIMARY KEY (quest_id, region_id)
);

CREATE INDEX quest_regions_region_id_idx ON quest_regions (region_id);

CREATE INDEX quests_status_scheduled_idx ON quests (status, scheduled_at);

-- character_logs after quests so quest_id can FK with ON DELETE SET NULL
CREATE TABLE character_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    character_id BIGINT NOT NULL REFERENCES characters (id) ON DELETE CASCADE,
    quest_id BIGINT REFERENCES quests (id) ON DELETE SET NULL,
    body TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX character_logs_character_created_idx
    ON character_logs (character_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- jobs and site
-- ---------------------------------------------------------------------------
CREATE TABLE background_jobs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    job_key TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL,
    lane TEXT NOT NULL DEFAULT 'default',
    state TEXT NOT NULL DEFAULT 'queued',
    attempts INT NOT NULL DEFAULT 0,
    payload JSONB NOT NULL DEFAULT '{}',
    error_message TEXT,
    lease_token BIGINT NOT NULL DEFAULT 0 CHECK (lease_token >= 0),
    lease_expires_at TIMESTAMPTZ,
    claimed_at TIMESTAMPTZ,
    attempt_deadline_at TIMESTAMPTZ,
    question_deadline_at TIMESTAMPTZ,
    completion_operation TEXT,
    completion_payload JSONB,
    next_run_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT background_jobs_state_check CHECK (
        state IN (
            'queued', 'running', 'succeeded', 'retry_wait',
            'repair_required', 'dead', 'cancelled'
        )
    ),
    CONSTRAINT job_lease_state CHECK (
        (state = 'running' AND lease_expires_at IS NOT NULL AND claimed_at IS NOT NULL AND attempt_deadline_at IS NOT NULL) OR
        (state <> 'running' AND lease_expires_at IS NULL AND claimed_at IS NULL AND attempt_deadline_at IS NULL)
    ),
    CONSTRAINT job_completion_pair CHECK ((completion_operation IS NULL) = (completion_payload IS NULL)),
    CONSTRAINT agent_question_deadline CHECK ((kind = 'agent_question') = (question_deadline_at IS NOT NULL))
);

CREATE INDEX background_jobs_claim_idx
    ON background_jobs (lane, state, next_run_at);

CREATE INDEX background_jobs_expiry_idx
    ON background_jobs (lease_expires_at) WHERE state = 'running';
CREATE INDEX background_jobs_question_deadline_idx
    ON background_jobs (question_deadline_at)
    WHERE kind = 'agent_question' AND state IN ('queued', 'retry_wait', 'running');

CREATE TABLE idempotency_keys (
    endpoint TEXT NOT NULL,
    key TEXT NOT NULL,
    actor_id BIGINT NOT NULL REFERENCES members (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (endpoint, key)
);

CREATE TABLE agent_questions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    job_id BIGINT NOT NULL UNIQUE REFERENCES background_jobs (id),
    question TEXT NOT NULL,
    history JSONB,
    result JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE discord_activity_events (
    event_id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    discord_user_id TEXT NOT NULL,
    channel_id TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    amount DOUBLE PRECISION NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE bot_heartbeats (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payload JSONB NOT NULL DEFAULT '{}',
    received_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE site_settings (
    key TEXT PRIMARY KEY,
    document_id BIGINT REFERENCES documents (id),
    payload JSONB NOT NULL DEFAULT '{}',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Specification SQL interpreter for the outer document audience (D3/D28).
-- Tokens are signed by a leading !; no cryptographic signature is implied.
-- +goose StatementBegin
CREATE FUNCTION document_readable(
    document_id UUID, author_id UUID, document_status TEXT,
    legacy_visibility TEXT, audience JSONB,
    viewer_id UUID, viewer_roles TEXT[], viewer_handle TEXT,
    viewer_admin BOOLEAN, viewer_live_dm BOOLEAN, reader_ids UUID[]
) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    token JSONB;
    body TEXT;
    principal_kind TEXT;
    principal_value TEXT;
    denied BOOLEAN;
    member_deny BOOLEAN := FALSE;
    member_allow BOOLEAN := FALSE;
    role_deny BOOLEAN := FALSE;
    role_allow BOOLEAN := FALSE;
    legacy_dm_tier BOOLEAN;
BEGIN
    IF viewer_id IS NOT NULL AND (COALESCE(viewer_admin, FALSE) OR author_id = viewer_id) THEN
        RETURN TRUE;
    END IF;
    IF document_status IS DISTINCT FROM 'published' THEN
        RETURN FALSE;
    END IF;
    IF audience IS NULL OR audience = 'null'::jsonb THEN
        -- Approved role-DM retains the current profile repair; active archon
        -- independently retains the source's legacy tier. This does not grant
        -- role:dm to archons or change command authority.
        legacy_dm_tier := viewer_id IS NOT NULL AND (
            COALESCE(viewer_live_dm, FALSE) OR COALESCE('archon' = ANY(viewer_roles), FALSE)
        );
        RETURN CASE legacy_visibility
            WHEN 'public' THEN TRUE
            WHEN 'dm_only' THEN legacy_dm_tier
            WHEN 'restricted' THEN legacy_dm_tier
                AND COALESCE(document_id = ANY(reader_ids), FALSE)
            ELSE FALSE END;
    END IF;
    IF jsonb_typeof(audience) <> 'array' THEN
        RETURN FALSE;
    END IF;
    FOR token IN SELECT value FROM jsonb_array_elements(audience) LOOP
        IF jsonb_typeof(token) <> 'string' THEN RETURN FALSE; END IF;
        body := token #>> '{}';
        denied := left(body, 1) = '!';
        IF denied THEN body := substr(body, 2); END IF;
        principal_kind := split_part(body, ':', 1);
        principal_value := substr(body, strpos(body, ':') + 1);
        IF strpos(body, ':') = 0 OR principal_kind NOT IN ('role', 'member') OR principal_value = '' THEN
            RETURN FALSE;
        END IF;
        IF viewer_id IS NULL THEN CONTINUE; END IF;
        IF principal_kind = 'member' AND (
            principal_value = viewer_id::text OR
            (COALESCE(viewer_handle, '') <> '' AND principal_value = '@' || viewer_handle)
        ) THEN
            IF denied THEN member_deny := TRUE; ELSE member_allow := TRUE; END IF;
        ELSIF principal_kind = 'role' AND COALESCE(principal_value = ANY(viewer_roles), FALSE) THEN
            IF denied THEN role_deny := TRUE; ELSE role_allow := TRUE; END IF;
        END IF;
    END LOOP;
    RETURN NOT member_deny AND (member_allow OR (NOT role_deny AND role_allow));
END;
$$;
-- +goose StatementEnd


-- +goose Down
DROP FUNCTION document_readable(UUID, UUID, TEXT, TEXT, JSONB, UUID, TEXT[], TEXT, BOOLEAN, BOOLEAN, UUID[]);
